$ErrorActionPreference='Stop'; . (Join-Path $PSScriptRoot 'windows_paths.ps1'); $memoryIdentity=[Security.Principal.WindowsIdentity]::GetCurrent(); $memoryTaskName='AI Memory Health Watch'; $memoryExisting=Get-ScheduledTask -TaskName $memoryTaskName -ErrorAction SilentlyContinue; $memoryTaskArgument='"'+(Join-Path $PSScriptRoot 'watch_ai_memory.py')+'"'; if ($memoryExisting -and (@($memoryExisting.Actions)[0].Arguments -ne $memoryTaskArgument -or @($memoryExisting.Actions)[0].Execute -ne $memoryPythonw)) { throw 'An unexpected AI Memory Health Watch task exists.' }; $memoryAction=New-ScheduledTaskAction -Execute $memoryPythonw -Argument $memoryTaskArgument -WorkingDirectory $memoryData; $memoryLogon=New-ScheduledTaskTrigger -AtLogOn -User $memoryIdentity.Name; $memoryLogon.Delay='PT30S'; $memoryRepeat=New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(1) -RepetitionInterval (New-TimeSpan -Minutes 5); $memoryPrincipal=New-ScheduledTaskPrincipal -UserId $memoryIdentity.Name -LogonType Interactive -RunLevel Limited; $memorySettings=New-ScheduledTaskSettingsSet -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Minutes 3) -RestartCount 2 -RestartInterval (New-TimeSpan -Minutes 1); $null=Register-ScheduledTask -TaskName $memoryTaskName -Action $memoryAction -Trigger @($memoryLogon,$memoryRepeat) -Principal $memoryPrincipal -Settings $memorySettings -Description 'Per-user ai-memory health, native recovery and verified private backups. No stored password.' -Force; $memoryDesktop=[Environment]::GetFolderPath('Desktop'); $memoryShell=New-Object -ComObject WScript.Shell; $memoryLink=$memoryShell.CreateShortcut((Join-Path $memoryDesktop 'AI Memory Status.lnk')); $memoryLink.TargetPath=Join-Path $env:SystemRoot 'System32\notepad.exe'; $memoryLink.Arguments='"'+(Join-Path $PSScriptRoot 'status.txt')+'"'; $memoryLink.Save(); $memoryLink=$memoryShell.CreateShortcut((Join-Path $memoryDesktop 'AI Memory Check Now.lnk')); $memoryLink.TargetPath=$memoryPythonw; $memoryLink.Arguments=$memoryTaskArgument+' --show'; $memoryLink.WindowStyle=7; $memoryLink.Save(); Set-Content -LiteralPath (Join-Path $memoryDesktop 'AI Memory Web.url') -Value "[InternetShortcut]`r`nURL=http://127.0.0.1:49374/web" -Encoding ascii
